DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public.guard_account_content()'::regprocedure) INTO f; f:=replace(f,'IF actor.is_demo THEN IF j->>','IF actor.is_demo THEN IF j->>''crew_id'' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM crews WHERE id=(j->>''crew_id'')::uuid AND is_demo) THEN RAISE EXCEPTION ''demo_only''; END IF; IF j->>''boss_id'' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM bosses WHERE id=(j->>''boss_id'')::uuid AND is_demo) THEN RAISE EXCEPTION ''demo_only''; END IF; IF j->>''checkin_id'' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM checkins WHERE id=(j->>''checkin_id'')::uuid AND is_demo) THEN RAISE EXCEPTION ''demo_only''; END IF; IF j->>');EXECUTE f;
SELECT pg_get_functiondef('public.guard_profile_privileges()'::regprocedure) INTO f; f:=replace(f,'BEGIN IF auth.uid()','BEGIN IF auth.uid()=OLD.id AND OLD.is_demo AND (NEW.handle IS DISTINCT FROM OLD.handle OR NEW.display_name IS DISTINCT FROM OLD.display_name) THEN RAISE EXCEPTION ''demo_protected''; END IF; IF auth.uid()');EXECUTE f;
SELECT pg_get_functiondef('public.active_season()'::regprocedure) INTO f;f:=replace(f,'RETURN (SELECT to_jsonb(s) FROM public.seasons s WHERE CASE','RETURN (SELECT to_jsonb(s) FROM public.seasons s WHERE NOT s.archived AND CASE');EXECUTE f;
SELECT pg_get_functiondef('public.join_challenge(text)'::regprocedure) INTO f;f:=replace(f,'IF c.id IS NULL','IF c.archived THEN RAISE EXCEPTION ''challenge_closed''; END IF; IF c.id IS NULL');EXECUTE f;
END $$;